#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_authorization: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::StartAuthorizationFacts>> = Mutex::new(None);
  pub static ref IN_applied_lifecycle: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::AppliedLifecycleSnapshot>> = Mutex::new(None);
  pub static ref OUT_control_frame: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::ControlFrame>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_authorization.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_applied_lifecycle.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_control_frame.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_authorization(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::StartAuthorizationFacts) -> bool
{
  unsafe {
    let guard = IN_authorization.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_applied_lifecycle(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::AppliedLifecycleSnapshot) -> bool
{
  unsafe {
    let guard = IN_applied_lifecycle.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_control_frame(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::ControlFrame) -> bool
{
  unsafe {
    *OUT_control_frame.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
